request_definition_hash <- function(dates, cds_area, config, buffer_degrees=NULL, align_to_source_grid=NULL) {
  digest::digest(list(dates=as.character(sort(unique(as.Date(dates)))), dataset=config$cds$dataset_short_name, variable=config$cds$variable, daily_statistic=config$cds$daily_statistic, frequency=config$cds$frequency, area=as.numeric(cds_area), source_grid_alignment=isTRUE(align_to_source_grid), buffer_degrees=buffer_degrees), algo="xxhash32")
}
build_era5_mintemp_requests <- function(planned_dates, cds_area, config) {
  d <- sort(unique(as.Date(planned_dates))); if(!length(d)) return(list()); if(length(cds_area)!=4 || cds_area[1]<=cds_area[3] || cds_area[2]>=cds_area[4]) stop("CDS area must be north, west, south, east"); g <- split(d, format(d,"%Y-%m")); lapply(g, function(x) { ym <- format(x[1],"%Y-%m"); h <- request_definition_hash(x,cds_area,config,config$spatial$api_bbox_buffer_degrees %||% NULL,config$spatial$align_request_to_source_grid %||% FALSE); target <- sprintf("era5_mintemp_daily_%s-%s_%s.nc", substr(ym,1,4),substr(ym,6,7),substr(h,1,8)); list(dataset_short_name=config$cds$dataset_short_name, product_type=config$cds$product_type, variable=config$cds$variable, year=substr(ym,1,4), month=substr(ym,6,7), day=format(x,"%d"), daily_statistic=config$cds$daily_statistic, time_zone=config$cds$time_zone, frequency=config$cds$frequency, data_format=config$cds$data_format, download_format=config$cds$download_format, area=as.numeric(cds_area), source_grid_alignment=isTRUE(config$spatial$align_request_to_source_grid), buffer_degrees=config$spatial$api_bbox_buffer_degrees %||% NULL, request_hash=h, target=target) })
}
validate_cds_request_structure <- function(request) { stopifnot(is.list(request)); required <- c("dataset_short_name","product_type","variable","year","month","day","daily_statistic","time_zone","frequency","data_format","download_format","area","target"); if(!all(required %in% names(request))) stop("Missing CDS request fields"); if(request$dataset_short_name!="derived-era5-single-levels-daily-statistics"||request$variable!="2m_temperature"||request$daily_statistic!="daily_minimum") stop("Invalid ERA5 request specification"); if(!grepl("^\\d{4}$",request$year)||!grepl("^\\d{2}$",request$month)||any(!grepl("^\\d{2}$",request$day))||any(as.integer(request$day)<1|as.integer(request$day)>31)) stop("Invalid request date fields"); if(length(request$area)!=4||request$area[1]<=request$area[3]||request$area[2]>=request$area[4]) stop("Invalid area"); if("user" %in% names(request)||request$data_format!="netcdf"||request$download_format!="unarchived") stop("Invalid or unsafe CDS request fields"); TRUE }
write_cds_request_manifests <- function(requests, run_dir) { fs::dir_create(run_dir,recurse=TRUE); rows <- if(length(requests)) do.call(rbind,lapply(requests,function(x) data.frame(year=x$year,month=x$month,days=paste(x$day,collapse=","),area=paste(x$area,collapse=","),target=x$target,stringsAsFactors=FALSE))) else data.frame(); utils::write.csv(rows,file.path(run_dir,"request_manifest.csv"),row.names=FALSE); jsonlite::write_json(requests,file.path(run_dir,"request_manifest.json"),pretty=TRUE,auto_unbox=TRUE); invisible(rows) }
